using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.EventSystems;using UnityEngine.UI;
public static class StreetLegendMenuSceneBuilder{[MenuItem("Street Legend/Build Main Menu Scene")]public static void Build(){PlayerSettings.defaultInterfaceOrientation=UIOrientation.LandscapeLeft;PlayerSettings.allowedAutorotateToLandscapeLeft=true;PlayerSettings.allowedAutorotateToLandscapeRight=true;PlayerSettings.allowedAutorotateToPortrait=false;PlayerSettings.allowedAutorotateToPortraitUpsideDown=false;var s=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var go=new GameObject("Street Legend Menu Flow");go.AddComponent<StreetLegendMainMenu>();new GameObject("Menu EventSystem",typeof(EventSystem),typeof(StandaloneInputModule));var cam=new GameObject("Menu Camera").AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.015f,.03f,.07f);cam.transform.position=new Vector3(0,0,-10);if(!AssetDatabase.IsValidFolder("Assets/Scenes"))AssetDatabase.CreateFolder("Assets","Scenes");EditorSceneManager.SaveScene(s,"Assets/Scenes/StreetLegend_MainMenu.unity");Debug.Log("Main menu scene generated.");}}